#!/bin/bash
# Generated by deploy/make-install.sh from deploy/: edit those files and run it.
# docs/deploy.md says how to fetch, check and run this.
set -euo pipefail
umask 077
dir=$(mktemp -d)
trap 'rm -rf "${dir:?}"' EXIT
cat >"$dir/setup.sh" <<'FRICT_INSTALL_EOF'
#!/bin/bash
# Sets the deployment server up, or upgrades it, from the files beside this
# script. deploy/install.sh carries them; docs/deploy.md runs it.
#
# Usage: setup.sh [PUBLIC_KEY]
# PUBLIC_KEY, one ssh-ed25519 line, becomes the deploy user's only key. Without
# it the installed key stays. frict.env and the Duo client secret are made only
# when missing.
set -euo pipefail
export LC_ALL=C PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
umask 022

src=$(dirname "$0")
user=frict-deploy
dir=/srv/frict
host=api.frict.app
key=${1-}

if (($# > 1)) || [[ -n $key && ! $key =~ ^ssh-ed25519\ [A-Za-z0-9+/]{68}(\ [[:print:]]*)?$ ]]; then
  echo "want at most one argument, one ssh-ed25519 public key line. Nothing changed." >&2
  exit 2
fi

visudo -cqf "$src/sudoers"
getent passwd "$user" >/dev/null || useradd --create-home --shell /bin/sh "$user"
home=$(getent passwd "$user" | cut -d: -f6)
install -d -o root -g root -m 0755 "$home/.ssh" "$dir"

exec 9>"$dir/.lock"
flock -n 9 || { echo "Waiting for the running deploy to finish."; flock 9; }

install -o root -g root -m 0755 "$src/frict-deploy" /usr/local/bin/frict-deploy
install -o root -g root -m 0440 "$src/sudoers" /etc/sudoers.d/frict-deploy
visudo -cq
install -o root -g root -m 0644 "$src/compose.yaml" "$dir/compose.yaml"
install -d -o 65532 -g 65532 -m 0700 "$dir/data" "$dir/secrets"

if [[ -n $key ]]; then
  printf 'restrict,command="/usr/bin/sudo -n /usr/local/bin/frict-deploy" %s\n' "$key" |
    install -o root -g root -m 0644 /dev/stdin "$home/.ssh/authorized_keys"
fi
secret=$dir/secrets/duo-client-secret
[[ -e $secret ]] || openssl rand -hex 20 | install -o 65532 -g 65532 -m 0400 /dev/stdin "$secret"
env=$dir/frict.env
[[ -e $env ]] || install -o root -g root -m 0600 /dev/stdin "$env" <<ENV
# frict-server's configuration. cmd/frict-server/main.go documents each variable.
# compose.yaml sets FRICT_LISTEN, FRICT_DB_PATH, FRICT_CLIENT_SECRET_FILE, FRICT_TRUSTED_PROXIES and FRICT_ATTESTATION; its values win over this file.

# Needed now: the API hostname typed into Authentik's Duo stage.
FRICT_API_HOSTNAME=$host
# Needed now: the client ID typed into Authentik's Duo stage, with the secret in $secret.
FRICT_CLIENT_ID=DI$(openssl rand -hex 9 | tr a-f A-F)

# Needed to enroll phones: the app's signing certificate SHA-256 digests from Play Console, comma-separated (docs/deploy.md). Empty refuses every enrollment.
#FRICT_APP_SIGNING_CERTS=

# Only for push, later: the Firebase project to push through. Set both FCM lines or neither.
#FRICT_FCM_PROJECT_ID=
# Only for push, later: its FCM sender key, saved as $dir/secrets/fcm-sa.json.
#FRICT_FCM_CREDENTIALS_FILE=/secrets/fcm-sa.json

# Optional, default 60s: how long a push waits for the device's answer, 60s to 120s.
#FRICT_CHALLENGE_TTL=60s
# Optional, default 10: pushes since a user's last successful login before the cooldown applies.
#FRICT_PUSH_CAP=10
# Optional, default 15m: once over the cap, the least time between pushes.
#FRICT_PUSH_COOLDOWN=15m
# Optional, default 2: "I didn't start this" answers that pause the user's pushes ...
#FRICT_NOT_ME_COUNT=2
# Optional, default 60m: ... when given within this long.
#FRICT_NOT_ME_WINDOW=60m
# Optional, default 30m: how long the pause lasts.
#FRICT_PAUSE=30m
ENV

echo "Installed $user and $dir."
if [[ ! -s $home/.ssh/authorized_keys ]]; then
  echo "No deploy key: run this again with the public key line (docs/deploy.md)."
fi
cat <<MSG

On your workstation, save this server's host key for the deploy job:

printf '%s\n' '$host $(cut -d' ' -f1,2 /etc/ssh/ssh_host_ed25519_key.pub)' | gh secret set DEPLOY_KNOWN_HOSTS --repo frict-auth/frict-server --env production

Authentik's Duo stage: API hostname $(sed -n 's/^FRICT_API_HOSTNAME=//p' "$env"), client ID $(sed -n 's/^FRICT_CLIENT_ID=//p' "$env"),
client secret: sudo cat $secret
MSG
FRICT_INSTALL_EOF
cat >"$dir/frict-deploy" <<'FRICT_INSTALL_EOF'
#!/bin/bash
# Deploys one digest of the frict-server image on the deployment server. Runs as
# root through sudo from the forced command of GitHub's deploy key, so
# SSH_ORIGINAL_COMMAND is the client's input: one sha256 digest and nothing
# else. docs/deploy.md.
#
# Output reaches a public Actions log; frict-server's own logs stay in logs/.
set -euo pipefail
export LC_ALL=C PATH=/usr/local/bin:/usr/bin:/bin
umask 077

image=ghcr.io/frict-auth/frict-server
dir=/srv/frict
url=http://127.0.0.1:8081/healthz
health_wait=20

digest=${SSH_ORIGINAL_COMMAND-}
if [[ ! $digest =~ ^sha256:[0-9a-f]{64}$ ]]; then
  echo "REFUSED: want sha256:<64 lowercase hex digits> and nothing else. Nothing changed." >&2
  exit 2
fi

cd "$dir"
mkdir -p backups logs
exec 9>.lock
if ! flock -n 9; then
  echo "REFUSED: another deploy is running. Nothing changed." >&2
  exit 1
fi

# A lost SSH connection must not stop a deploy halfway: output goes to a file
# and is copied to the client at the end.
stamp=$(date -u +%Y%m%dT%H%M%SZ)-${digest:7:12}
log=logs/$stamp.log
exec 3>&1 >"$log" 2>&1
trap '' HUP PIPE
finish() {
  local code=$?
  cat "$log" >&3
  exit "$code"
}
trap finish EXIT

state() { if [[ -f .env ]]; then sed -n "s/^$1=//p" .env; fi; }
current=$(state FRICT_DIGEST)
current_commit=$(state FRICT_MAIN_COMMIT)

# dc DIGEST ARGS...: docker compose with the image at DIGEST.
dc() { FRICT_DIGEST=$1 docker compose --ansi never --progress plain "${@:2}"; }

container() { dc "$1" ps --all --quiet frict-server; }

# runs DIGEST: the container is running exactly that image.
runs() {
  local id image_id digests
  id=$(container "$1") && [[ -n $id ]] || return 1
  [[ $(docker inspect --format '{{.State.Running}}' "$id") == true ]] || return 1
  image_id=$(docker inspect --format '{{.Image}}' "$id") || return 1
  digests=$(docker image inspect --format '{{join .RepoDigests "\n"}}' "$image_id") || return 1
  [[ $'\n'$digests$'\n' == *$'\n'"$image@$1"$'\n'* ]]
}

healthy() { curl -fs --max-time 5 --noproxy '*' -o /dev/null "$url"; }

# comes_up DIGEST: DIGEST is running and healthy within health_wait seconds.
# A freshly created container that restarts has crashed.
comes_up() {
  local id deadline=$((SECONDS + health_wait))
  id=$(container "$1") && [[ -n $id ]] || return 1
  until healthy; do
    if [[ $(docker inspect --format '{{.RestartCount}}' "$id") != 0 ]]; then
      echo "frict-server exited after starting"
      return 1
    fi
    if ((SECONDS >= deadline)); then
      echo "/healthz did not answer 200 within ${health_wait}s"
      return 1
    fi
    sleep 1
  done
  runs "$1" || { echo "the running container is not $image@$1"; return 1; }
}

# save_logs DIGEST: keeps the container's own log; compose removes it with the
# container.
save_logs() {
  local id
  id=$(container "$1") && [[ -n $id ]] && docker logs "$id" >"logs/$stamp-server-${1:7:12}.log" 2>&1
}

# go_back never returns.
go_back() {
  echo "DEPLOY FAILED: $image@$digest"
  save_logs "$digest" || echo "could not save frict-server's log"
  echo "frict-server's log is in $dir/logs on the deployment server."
  if [[ -z $current || $current == "$digest" ]]; then
    dc "$digest" stop frict-server || echo "could not stop frict-server"
    echo "SERVER IS DOWN: there is no previous version to go back to."
    exit 1
  fi
  echo "Going back to $current"
  if dc "$current" up --detach --force-recreate --pull never frict-server && comes_up "$current"; then
    echo "WENT BACK: $image@$current is running and healthy."
    exit 1
  fi
  save_logs "$current" || echo "could not save frict-server's log"
  echo "SERVER IS DOWN: going back to $current failed too."
  if grep -qs "newer than this binary" "logs/$stamp-server-${current:7:12}.log"; then
    echo "The new version migrated the database and the previous one refuses the newer schema."
    echo "Restore $dir/backups/$stamp.tar (docs/deploy.md, Restore)."
  fi
  exit 1
}

if ! docker pull --quiet "$image@$digest"; then
  echo "REFUSED: cannot pull $image@$digest. Nothing changed."
  exit 1
fi
commit=$(docker image inspect --format '{{index .Config.Labels "app.frict.main-commit"}}' "$image@$digest")
if [[ ! $commit =~ ^[1-9][0-9]{0,8}$ ]]; then
  echo "REFUSED: the image has no app.frict.main-commit label. Nothing changed."
  exit 1
fi
if [[ -n $current ]] && ((commit < current_commit)); then
  echo "REFUSED: built from commit $commit on main, older than the deployed $current_commit. To go back, revert on main. Nothing changed."
  exit 1
fi

if ! dc "$digest" config --quiet; then
  echo "REFUSED: $dir/compose.yaml or what it names is broken. Nothing changed."
  exit 1
fi

# Nothing has the database open between stop and start, so the copy is
# consistent.
replace() {
  echo "Deploying $image@$digest (commit $commit on main)"
  dc "$digest" stop frict-server &&
    dc "$digest" create --force-recreate --pull never frict-server &&
    docker cp "$(container "$digest"):/data" - >"backups/$stamp.tar" &&
    echo "Backed up /data to $dir/backups/$stamp.tar" &&
    dc "$digest" start frict-server &&
    comes_up "$digest"
}
previous=$current
if [[ $current == "$digest" ]]; then
  previous=$(state FRICT_PREVIOUS_DIGEST)
fi

if runs "$digest" && healthy; then
  echo "$image@$digest is already running and healthy. Not restarted."
else
  replace || go_back
fi

if ! printf '%s\n' "FRICT_DIGEST=$digest" "FRICT_MAIN_COMMIT=$commit" "FRICT_PREVIOUS_DIGEST=$previous" >.env.new || ! mv .env.new .env; then
  echo "DEPLOY FAILED: $image@$digest is running and healthy, but $dir/.env doesn't record it. Fix that and deploy again."
  exit 1
fi
echo "OK: $image@$digest is running and healthy. Previous: ${previous:-none}"
FRICT_INSTALL_EOF
cat >"$dir/sudoers" <<'FRICT_INSTALL_EOF'
# /etc/sudoers.d/frict-deploy. docs/deploy.md.
Defaults!/usr/local/bin/frict-deploy env_keep = "SSH_ORIGINAL_COMMAND", !env_check
frict-deploy ALL=(root) NOPASSWD: /usr/local/bin/frict-deploy ""
FRICT_INSTALL_EOF
cat >"$dir/compose.yaml" <<'FRICT_INSTALL_EOF'
# frict-server on the deployment server: /srv/frict/compose.yaml. docs/deploy.md.
name: frict

services:
  frict-server:
    image: ghcr.io/frict-auth/frict-server@${FRICT_DIGEST:?set by frict-deploy}
    restart: unless-stopped
    # frict-server waits up to 15 s for in-flight requests.
    stop_grace_period: 20s
    read_only: true
    cap_drop: [ALL]
    security_opt: ["no-new-privileges:true"]
    env_file: frict.env
    environment:
      FRICT_LISTEN: ":8080"
      FRICT_DB_PATH: /data/frict.db
      FRICT_CLIENT_SECRET_FILE: /secrets/duo-client-secret
      # nginx reaches the published port through this network's gateway.
      FRICT_TRUSTED_PROXIES: 10.231.0.1
      # Only Google-rooted hardware keys enroll; frict.env can't relax it.
      FRICT_ATTESTATION: strict
    ports:
      - 127.0.0.1:8081:8080
    volumes:
      - type: bind
        source: ./data
        target: /data
        bind:
          create_host_path: false
      - type: bind
        source: ./secrets
        target: /secrets
        read_only: true
        bind:
          create_host_path: false

networks:
  default:
    ipam:
      config:
        - subnet: 10.231.0.0/24
          gateway: 10.231.0.1
FRICT_INSTALL_EOF
bash "$dir/setup.sh" "$@"
